1	/**
2	 * Scoped per testing.md: this component's own contract (given props, does it render the right
3	 * branch and wire the right handler) — not ZimmSlideIndicator's own segment/clamp logic, which
4	 * is proven in its own index.test.tsx and rendered here for real (it is a lightweight,
5	 * side-effect-free presentational atom, so composing it directly costs nothing and gives real
6	 * integration confidence that this component passes it the right `count`/`activeIndex`).
7	 */
8	import React from 'react';
9	import { describe, test, expect, vi } from 'vitest';
10	import { render, screen, fireEvent } from '@testing-library/react';
11	import userEvent from '@testing-library/user-event';
12	import { IntlProvider } from 'react-intl';
13	import { ZimmProductCardMedia } from './index';
14	import type { ZimmProductCardMediaImage } from './index';
15	import { ZimmProductCardMedia as ZimmProductCardMediaRecipe } from './zimmProductCardMedia.css';
16	import { CARD_SLOT } from '../../organisms/zimmProductCard/zimmProductCardShared';
17	
18	// Flat parts object covering both this component's own recipe AND ZimmSlideIndicator's
19	// (root/dot) — the same mocked useMultiStyleConfig is shared by both since neither test setup
20	// nor Chakra itself cares which recipe name asked for it. Same precedent as
21	// zimmSizeChipGroup/index.test.tsx's comment on its composed atom's unresolved styles.chip.
22	vi.mock('@chakra-ui/react', async (importOriginal) => {
23	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
24	  return {
25	    ...actual,
26	    useMultiStyleConfig: () => ({
27	      root: {},
28	      scrollContainer: {},
29	      slide: {},
30	      image: {},
31	      hoverSwapBase: {},
32	      hoverSwapOverlay: {},
33	      badge: {},
34	      badgeLabel: {},
35	      close: {},
36	      carousel: {},
37	      arrowButton: {},
38	      indicatorWrapper: {},
39	      dot: {},
40	    }),
41	  };
42	});
43	
44	// ChevronLeftIcon / ChevronRightIcon / CloseIcon: the icons barrel has the Vitest SVG
45	// side-effect issue documented in .claude/rules/testing.md's "Known gap: ZimmIcon throws under
46	// Vitest" section. Mocked at the same relative specifier this component imports them from.
47	vi.mock('../../../icons', () => ({
48	  ChevronLeftIcon: () => null,
49	  ChevronRightIcon: () => null,
50	  CloseIcon: () => null,
51	}));
52	
53	const wrap = (ui: React.ReactElement) =>
54	  render(
55	    <IntlProvider locale="en" defaultLocale="en">
56	      {ui}
57	    </IntlProvider>,
58	  );
59	
60	const PRIMARY: ZimmProductCardMediaImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
61	const HOVER: ZimmProductCardMediaImage = { src: 'hover.jpg', alt: 'Zimmermann dress, on model' };
62	const GALLERY: ZimmProductCardMediaImage[] = [
63	  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
64	  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
65	  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
66	];
67	
68	/** Mocks the scroll container's native `scrollTo` (absent under jsdom — see index.tsx's own
69	 *  comment) so an arrow click can be asserted against a spy instead of throwing. */
70	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
71	  // HTMLElement already types `scrollTo` (lib.dom.d.ts) — jsdom just doesn't implement it at
72	  // runtime, so a plain mock-function assignment is enough; no cast needed.
73	  const scrollContainer = screen.getByTestId('card-media-scroll');
74	  const scrollTo = vi.fn();
75	  scrollContainer.scrollTo = scrollTo;
76	  return scrollTo;
77	};
78	
79	describe('ZimmProductCardMedia — AC1: primary image renders with minimal props', () => {
80	  test('renders the primary image when hoverImage, images and showControls are all absent/false', () => {
81	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
82	    const img = screen.getByRole('img', { name: PRIMARY.alt });
83	    expect(img).toHaveAttribute('src', PRIMARY.src);
84	  });
85	});
86	
87	describe('ZimmProductCardMedia — alt text', () => {
88	  test('every rendered gallery image carries its own meaningful alt text', () => {
89	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
90	    GALLERY.forEach((image) => {
91	      expect(screen.getByRole('img', { name: image.alt })).toBeInTheDocument();
92	    });
93	  });
94	
95	  test('a hover-swap pair keeps both images accessible by their own alt text', () => {
96	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} />);
97	    expect(screen.getByRole('img', { name: PRIMARY.alt })).toBeInTheDocument();
98	    expect(screen.getByRole('img', { name: HOVER.alt })).toBeInTheDocument();
99	  });
100	});
101	
102	describe('ZimmProductCardMedia — lazy/eager loading', () => {
103	  test('the primary image lazy-loads by default (priority absent)', () => {
104	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
105	    const img = screen.getByRole('img', { name: PRIMARY.alt });
106	    expect(img).toHaveAttribute('loading', 'lazy');
107	    expect(img).toHaveAttribute('decoding', 'async');
108	  });
109	
110	  test('the primary image loads eagerly when priority is true', () => {
111	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} priority />);
112	    const img = screen.getByRole('img', { name: PRIMARY.alt });
113	    expect(img).not.toHaveAttribute('loading');
114	    expect(img).toHaveAttribute('decoding', 'async');
115	  });
116	
117	  test('non-primary gallery images are always lazy, even when priority is true', () => {
118	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls priority />);
119	    expect(screen.getByRole('img', { name: GALLERY[0].alt })).not.toHaveAttribute('loading');
120	    expect(screen.getByRole('img', { name: GALLERY[1].alt })).toHaveAttribute('loading', 'lazy');
121	    expect(screen.getByRole('img', { name: GALLERY[2].alt })).toHaveAttribute('loading', 'lazy');
122	  });
123	
124	  test('the hover-swap overlay image is always lazy, even when priority is true', () => {
125	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} priority />);
126	    expect(screen.getByRole('img', { name: PRIMARY.alt })).not.toHaveAttribute('loading');
127	    expect(screen.getByRole('img', { name: HOVER.alt })).toHaveAttribute('loading', 'lazy');
128	  });
129	});
130	
131	describe('ZimmProductCardMedia — single image renders no paging affordance', () => {
132	  test('renders no arrow buttons and no slide indicator, even when showControls is true', () => {
133	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls />);
134	    expect(screen.queryAllByRole('button')).toHaveLength(0);
135	    expect(screen.queryByRole('group')).not.toBeInTheDocument(); // ZimmSlideIndicator's role=group
136	  });
137	
138	  test('a 1-entry images array behaves identically to an absent images array', () => {
139	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={[GALLERY[0]]} swapOnHover={false} showControls />);
140	    expect(screen.queryAllByRole('button')).toHaveLength(0);
141	    expect(screen.queryByRole('group')).not.toBeInTheDocument();
142	  });
143	});
144	
145	describe('ZimmProductCardMedia — arrows wrap at both ends', () => {
146	  test('Next from the last image wraps to the first, updates the indicator, and calls scrollTo with a plausible shape', async () => {
147	    const user = userEvent.setup();
148	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
149	    const scrollTo = mockScrollTo();
150	
151	    const next = screen.getByRole('button', { name: 'Next image' });
152	    await user.click(next); // 0 -> 1
153	    await user.click(next); // 1 -> 2 (last)
154	    scrollTo.mockClear();
155	    await user.click(next); // wraps 2 -> 0
156	
157	    expect(scrollTo).toHaveBeenCalledTimes(1);
158	    // jsdom reports clientWidth as 0 regardless of index, so the numeric offset itself cannot
159	    // prove which slide was requested — only that a plausible {left, behavior} shape was sent.
160	    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
161	    // The logical wrap is proven via the composed (real, unmocked) slide indicator's accessible
162	    // name, which reflects `activeIndex` from pure component state regardless of jsdom layout.
163	    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
164	  });
165	
166	  test('Previous from the first image wraps to the last, updates the indicator, and calls scrollTo with a plausible shape', async () => {
167	    const user = userEvent.setup();
168	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
169	    const scrollTo = mockScrollTo();
170	
171	    const previous = screen.getByRole('button', { name: 'Previous image' });
172	    await user.click(previous); // wraps 0 -> 2 (last)
173	
174	    expect(scrollTo).toHaveBeenCalledTimes(1);
175	    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
176	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
177	  });
178	});
179	
180	describe('ZimmProductCardMedia — remove (close) overlay', () => {
181	  test('renders nothing when onRemove is absent', () => {
182	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
183	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`)).not.toBeInTheDocument();
184	  });
185	
186	  test('renders nothing when onRemove is supplied without a usable removeLabel (defensive no-op)', () => {
187	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} onRemove={vi.fn()} />);
188	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`)).not.toBeInTheDocument();
189	  });
190	
191	  test('renders nothing when removeLabel is only whitespace', () => {
192	    wrap(
193	      <ZimmProductCardMedia
194	        primaryImage={PRIMARY}
195	        swapOnHover={false}
196	        showControls={false}
197	        onRemove={vi.fn()}
198	        removeLabel="   "
199	      />,
200	    );
201	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`)).not.toBeInTheDocument();
202	  });
203	
204	  test('renders a real, labelled button and calls onRemove on click when both are supplied', async () => {
205	    const onRemove = vi.fn();
206	    const user = userEvent.setup();
207	    wrap(
208	      <ZimmProductCardMedia
209	        primaryImage={PRIMARY}
210	        swapOnHover={false}
211	        showControls={false}
212	        onRemove={onRemove}
213	        removeLabel="Remove Zimmermann dress from wishlist"
214	      />,
215	    );
216	    const button = screen.getByRole('button', { name: 'Remove Zimmermann dress from wishlist' });
217	    expect(button.tagName).toBe('BUTTON');
218	    await user.click(button);
219	    expect(onRemove).toHaveBeenCalledTimes(1);
220	  });
221	});
222	
223	describe('ZimmProductCardMedia — badge overlay', () => {
224	  test('renders nothing when badge is absent', () => {
225	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
226	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).not.toBeInTheDocument();
227	  });
228	
229	  test('renders nothing when badge is only whitespace (same guard shape as removeLabel)', () => {
230	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} badge="   " />);
231	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).not.toBeInTheDocument();
232	  });
233	
234	  test('renders the label text when a real badge is supplied', () => {
235	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} badge="Runway" />);
236	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).toBeInTheDocument();
237	    expect(screen.getByText('Runway')).toBeInTheDocument();
238	  });
239	});
