241	describe('ZimmProductCardMedia — hover-swap keeps both images in the DOM simultaneously', () => {
242	  test('primary and hover images are both present at once, not conditionally rendered', () => {
243	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} />);
244	    expect(screen.getAllByRole('img')).toHaveLength(2);
245	  });
246	
247	  test('hover-swap does not activate without swapOnHover, even when hoverImage is supplied', () => {
248	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover={false} showControls={false} />);
249	    expect(screen.getAllByRole('img')).toHaveLength(1);
250	  });
251	
252	  test('hover-swap does not activate once a >1 image gallery takes over', () => {
253	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} images={GALLERY} swapOnHover showControls />);
254	    // 3 gallery images, no extra hoverImage layer on top of the first.
255	    expect(screen.getAllByRole('img')).toHaveLength(3);
256	  });
257	});
258	
259	describe('ZimmProductCardMedia — data-card-slot selector contract for the organism (Step 6)', () => {
260	  test('stamps every documented data-card-slot value when all optional slots are active', () => {
261	    wrap(
262	      <ZimmProductCardMedia
263	        primaryImage={PRIMARY}
264	        images={GALLERY}
265	        swapOnHover={false}
266	        showControls
267	        badge="Runway"
268	        onRemove={vi.fn()}
269	        removeLabel="Remove from wishlist"
270	      />,
271	    );
272	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.media}"]`)).toBeInTheDocument();
273	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).toBeInTheDocument();
274	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`)).toBeInTheDocument();
275	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.carousel}"]`)).toBeInTheDocument();
276	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.indicator}"]`)).toBeInTheDocument();
277	  });
278	});
279	
280	/**
281	 * Fix 1 (Scorer round 1, SFCC-236 Step 4 rework): the 19 tests above all render through the
282	 * `vi.mock('@chakra-ui/react', ...)` at the top of this file, which replaces useMultiStyleConfig
283	 * with a flat `{}` return for every part — none of them ever evaluate the REAL recipe object.
284	 * Proved live by the Scorer: deleting the recipe's HOVER_CAPABLE_QUERY media-query gate entirely
285	 * (making the desktop arrows permanently visible regardless of pointer capability) left the
286	 * whole suite green. These tests import the recipe module directly and call its exported
287	 * baseStyle(), bypassing the mock entirely — same technique as
288	 * zimmSizeChip.css.test.ts / zimmTextInput.css.test.ts.
289	 */
290	describe('ZimmProductCardMedia — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
291	  // Mirrors the module-private HOVER_CAPABLE_QUERY constant declared in
292	  // zimmProductCardMedia.css.ts, which the recipe does not export. If that literal ever changes
293	  // there, this must change too — the same "hardcode the literal the resolver actually produces"
294	  // precedent zimmSizeChip.css.test.ts / zimmTextInput.css.test.ts already use for their own
295	  // unexported `var(--zimm-*)` string literals.
296	  const HOVER_CAPABLE_QUERY = '@media (hover: hover) and (pointer: fine)';
297	
298	  test('carousel (arrows) and indicatorWrapper are mutually exclusive within the same media-query key', () => {
299	    const style = ZimmProductCardMediaRecipe.baseStyle();
300	
301	    // Touch / non-hover-capable pointers (outside the media query): indicator visible, arrows hidden.
302	    expect(style.indicatorWrapper.display).toBe('block');
303	    expect(style.carousel.display).toBe('none');
304	
305	    // Hover-capable pointers (inside the SAME media-query key, on both parts): arrows visible,
306	    // indicator hidden. Bracket-indexed via a `Record<string, unknown>` cast, same precedent as
307	    // zimmTextInput.css.test.ts's `row as Record<string, unknown>` — a `@media` key is a real
308	    // CSSObject selector at runtime but isn't one of SystemStyleObject's named literal keys.
309	    const carousel = style.carousel as Record<string, unknown>;
310	    const indicatorWrapper = style.indicatorWrapper as Record<string, unknown>;
311	    const carouselHoverBlock = carousel[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
312	    const indicatorHoverBlock = indicatorWrapper[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
313	
314	    expect(carouselHoverBlock.display).toBe('flex');
315	    expect(indicatorHoverBlock.display).toBe('none');
316	
317	    // Explicit mutual-exclusivity: never the same visibility on both parts, in either
318	    // media-query state.
319	    expect(style.carousel.display).not.toBe(style.indicatorWrapper.display);
320	    expect(carouselHoverBlock.display).not.toBe(indicatorHoverBlock.display);
321	  });
322	
323	  test("badge and close share the same fixed height, so their centred content lands on the same vertical line — regression guard: padding-only sizing on badge previously grew it to 64px against close's fixed 48px, landing badge text 9px below the close icon", () => {
324	    const style = ZimmProductCardMediaRecipe.baseStyle();
325	    expect(style.badge.height).toBe(style.close.height);
326	    expect(style.badge.display).toBe('flex');
327	    expect(style.badge.alignItems).toBe('center');
328	  });
329	
330	  test('close and arrowButton both carry the standard keyboard focus-visible outline', () => {
331	    const style = ZimmProductCardMediaRecipe.baseStyle();
332	    const expectedFocusVisible = {
333	      outline: 'var(--zimm-focus-ring)',
334	      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
335	    };
336	
337	    expect((style.close as Record<string, unknown>)._focusVisible).toEqual(expectedFocusVisible);
338	    expect((style.arrowButton as Record<string, unknown>)._focusVisible).toEqual(expectedFocusVisible);
339	  });
340	
341	  test('the scroll container carries the same focus-visible outline now that it is keyboard-focusable', () => {
342	    const style = ZimmProductCardMediaRecipe.baseStyle();
343	    expect((style.scrollContainer as Record<string, unknown>)._focusVisible).toEqual({
344	      outline: 'var(--zimm-focus-ring)',
345	      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
346	    });
347	  });
348	});
349	
350	describe('ZimmProductCardMedia — currentIndex re-clamps when the images gallery shrinks (Fix 3 regression)', () => {
351	  test('navigating to the last of 3 images then shrinking to 2 wraps correctly on the very next click', async () => {
352	    const user = userEvent.setup();
353	    const utils = wrap(
354	      <ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />,
355	    );
356	
357	    const next = screen.getByRole('button', { name: 'Next image' });
358	    await user.click(next); // 0 -> 1
359	    await user.click(next); // 1 -> 2 (last of 3)
360	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
361	
362	    // A colour-variant swap while the card stays mounted: the SAME instance re-renders with a
363	    // shorter images array.
364	    const SHRUNK_GALLERY = GALLERY.slice(0, 2);
365	    utils.rerender(
366	      <IntlProvider locale="en" defaultLocale="en">
367	        <ZimmProductCardMedia primaryImage={PRIMARY} images={SHRUNK_GALLERY} swapOnHover={false} showControls />
368	      </IntlProvider>,
369	    );
370	
371	    // ZimmSlideIndicator's own display-side clamp masks the stale state right here too — it also
372	    // reads "2 of 2", which is exactly what makes the underlying bug invisible without also
373	    // exercising the very next click below.
374	    expect(screen.getByRole('group', { name: 'Image 2 of 2' })).toBeInTheDocument();
375	
376	    const nextAfterShrink = screen.getByRole('button', { name: 'Next image' });
377	    await user.click(nextAfterShrink); // must wrap 2nd -> 1st on THIS click, not require a second one
378	
379	    expect(screen.getByRole('group', { name: 'Image 1 of 2' })).toBeInTheDocument();
380	  });
381	});
382	
383	describe('ZimmProductCardMedia — scrollend listener drives the touch indicator (Fix 4 regression)', () => {
384	  test('a real scrollend event with a simulated scroll position updates the indicator', () => {
385	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
386	    const container = screen.getByTestId('card-media-scroll');
387	
388	    // jsdom performs no real layout, so clientWidth/scrollWidth/scrollLeft all default to 0 —
389	    // but they ARE plain definable properties, so a real geometry can be simulated directly.
390	    // Slide width 300 x 3 slides, scrolled to slide index 1 (the 2nd of 3) => scrollLeft 300.
391	    const SIMULATED_SLIDE_WIDTH = 300;
392	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
393	    Object.defineProperty(container, 'scrollWidth', {
394	      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
395	      configurable: true,
396	    });
397	    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * 1, configurable: true });
398	
399	    // A raw `container.dispatchEvent(...)` bypasses @testing-library/react's configured
400	    // `eventWrapper`, so the resulting setCurrentIndex call is never flushed before the
401	    // assertion below runs. Routing the same native Event through RTL's generic `fireEvent`
402	    // call form (not one of its `fireEvent.<type>` convenience methods — `scrollend` isn't one
403	    // of those) dispatches the identical event while going through that act()-wrapping config.
404	    fireEvent(container, new Event('scrollend'));
405	
406	    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
407	  });
408	});
409	
410	describe('ZimmProductCardMedia — scroll container is keyboard-operable regardless of pointer capability (Fix 5)', () => {
411	  test('ArrowRight/ArrowLeft on the scroll container wrap at both ends, the same as the visible arrows, even with showControls false', () => {
412	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls={false} />);
413	    const container = screen.getByTestId('card-media-scroll');
414	
415	    expect(container).toHaveAttribute('tabindex', '0');
416	
417	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // 0 -> 1
418	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // 1 -> 2 (last)
419	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
420	
421	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // wraps 2 -> 0
422	    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
423	
424	    fireEvent.keyDown(container, { key: 'ArrowLeft' }); // wraps 0 -> 2 (last)
425	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
426	  });
427	
428	  test('the scroll container is not keyboard-focusable when there is only one image', () => {
429	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
430	    const container = screen.getByTestId('card-media-scroll');
431	    expect(container).not.toHaveAttribute('tabindex');
432	  });
433	});
