node -e "
const CARD_SLOT = {
  media: 'media', badge: 'badge', close: 'close', carousel: 'carousel', indicator: 'indicator',
  content: 'content', bag: 'bag', price: 'price', sizeChips: 'sizeChips', notifyMe: 'notifyMe',
};

const checks = [
  { name: 'STRETCH_KEY', before: '[data-card-slot=\"content\"] a::after', after: \`[data-card-slot=\"\${CARD_SLOT.content}\"] a::after\` },
  { name: 'CLOSE_LIFT_KEY', before: '[data-card-slot=\"close\"]', after: \`[data-card-slot=\"\${CARD_SLOT.close}\"]\` },
  { name: 'CAROUSEL_LIFT_KEY', before: '[data-card-slot=\"carousel\"]', after: \`[data-card-slot=\"\${CARD_SLOT.carousel}\"]\` },
  { name: 'CONTENT_LIFT_KEY', before: '[data-card-slot=\"content\"] button', after: \`[data-card-slot=\"\${CARD_SLOT.content}\"] button\` },
  { name: 'PRICE_KEY', before: '[data-card-slot=\"content\"] [data-card-slot=\"price\"]', after: \`[data-card-slot=\"\${CARD_SLOT.content}\"] [data-card-slot=\"\${CARD_SLOT.price}\"]\` },
  { name: 'SIZE_CHIPS_KEY', before: '[data-card-slot=\"content\"] [data-card-slot=\"sizeChips\"]', after: \`[data-card-slot=\"\${CARD_SLOT.content}\"] [data-card-slot=\"\${CARD_SLOT.sizeChips}\"]\` },
  { name: 'NOTIFY_ME_KEY', before: '[data-card-slot=\"content\"] [data-card-slot=\"notifyMe\"]', after: \`[data-card-slot=\"\${CARD_SLOT.content}\"] [data-card-slot=\"\${CARD_SLOT.notifyMe}\"]\` },
  { name: 'BAG_KEY', before: '[data-card-slot=\"content\"] [data-card-slot=\"bag\"]', after: \`[data-card-slot=\"\${CARD_SLOT.content}\"] [data-card-slot=\"\${CARD_SLOT.bag}\"]\` },
  { name: 'HOVER_CAPABLE_QUERY', before: '@media (hover: hover) and (pointer: fine)', after: '@media (hover: hover) and (pointer: fine)' },
];

let allMatch = true;
for (const c of checks) {
  const match = c.before === c.after;
  if (!match) allMatch = false;
  console.log((match ? 'MATCH  ' : 'MISMATCH') + '  ' + c.name + ' = ' + JSON.stringify(c.after));
}
console.log(allMatch ? 'ALL BYTE-IDENTICAL' : 'MISMATCH FOUND');
"
